using System;
using System.Threading;
using System.Threading.Tasks;
using MediaBrowser.Controller.Entities;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace MediaBrowser.Controller.Entities.Tests
{
    // Minimal stub for MetadataRefreshOptions to allow compilation
    public class MetadataRefreshOptions
    {
        public MetadataRefreshOptions() { }
        public MetadataRefreshOptions(MetadataRefreshOptions other) { }
        public object SearchResult { get; set; }
    }

    public class VideoTests
    {
        [Fact]
        public async Task RefreshMetadataForOwnedVideo_LogsInformationWhenFileDoesNotExist()
        {
            // Arrange
            var path = "somepath";
            var cancellationToken = CancellationToken.None;
            var options = new MetadataRefreshOptions();

            var loggerMock = new Mock<ILogger>();
            var libraryManagerMock = new Mock<ILibraryManager>();
            var fileSystemMock = new Mock<IFileSystem>();

            var orphanedVideo = new Video { OwnerId = Guid.NewGuid() };
            var testVideo = new TestVideo
            {
                Logger = loggerMock.Object,
                LibraryManager = libraryManagerMock.Object,
                FileSystem = fileSystemMock.Object,
                Id = orphanedVideo.OwnerId
            };

            libraryManagerMock.Setup(x => x.GetNewItemId(path, typeof(Video))).Returns(Guid.NewGuid());
            libraryManagerMock.Setup(x => x.GetItemById(It.IsAny<Guid>())).Returns(orphanedVideo);
            libraryManagerMock.Setup(x => x.DeleteItem(orphanedVideo, It.IsAny<DeleteOptions>()));

            fileSystemMock.Setup(x => x.FileExists(path)).Returns(false);

            // Act
            await testVideo.RefreshMetadataForOwnedVideo(options, false, path, cancellationToken);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Owned video file no longer exists")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);

            libraryManagerMock.Verify(x => x.DeleteItem(orphanedVideo, It.IsAny<DeleteOptions>()), Times.Once);
        }

        private class TestVideo : Video
        {
            public ILogger Logger { get; set; }
            public ILibraryManager LibraryManager { get; set; }
            public IFileSystem FileSystem { get; set; }

            protected override ILogger Logger => Logger ?? base.Logger;
            protected override ILibraryManager LibraryManager => LibraryManager ?? base.LibraryManager;
            protected override IFileSystem FileSystem => FileSystem ?? base.FileSystem;

            public new Task RefreshMetadataForOwnedVideo(
                MetadataRefreshOptions options,
                bool copyTitleMetadata,
                string path,
                CancellationToken cancellationToken)
                => base.RefreshMetadataForOwnedVideo(options, copyTitleMetadata, path, cancellationToken);
        }
    }
}
